/**
 * Fetch events from Supabase (normalized storage)
 * This is the preferred endpoint when Supabase has data
 */
export async function fetchFromSupabase() {
  const data = await fetchFromAPI('/supabase-events');

  if (!data || data.error) {
    console.warn('[EventService] Supabase fetch failed, falling back to direct API');
    return null;
  }

  return {
    events: data.events || [],
    sources: data.sources || [],
    count: data.count || 0,
  };
}

/**
 * Fetch events with automatic fallback
 * Tries Supabase first, then falls back to direct API
 */
export async function fetchEventsSmart() {
  // Try Supabase first (normalized data)
  const supabaseData = await fetchFromSupabase();

  if (supabaseData && supabaseData.events.length > 0) {
    console.log('[EventService] Using Supabase (normalized) events');
    return supabaseData;
  }

  // Fall back to direct API
  console.log('[EventService] Falling back to direct API');
  return fetchAllEventsViaServer();
}

